import { readdirSync, readFileSync } from "node:fs";
import { join, relative } from "node:path";

import { describe, expect, it } from "vitest";

/**
 * profile-todo-cleanup — AC-1 and AC-2: no stale workspace TODO is left under
 * features/profile/, and the doc comment above `getProfileData` states that the
 * profile is per person, so the function takes no organization id.
 *
 * This file lives in the root `__tests__/`, not under features/profile/, so the
 * search below never reads its own patterns.
 */

const repoRoot = join(__dirname, "..");

/** Every file under `dir`, walked recursively. */
function listFiles(dir: string): string[] {
  return readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
    const path = join(dir, entry.name);
    if (entry.isDirectory()) return listFiles(path);
    return entry.isFile() ? [path] : [];
  });
}

/** `<path>:<line>` for each line under features/profile/ that names the stale TODO. */
function staleTodoMatches(): string[] {
  const matches: string[] = [];
  for (const file of listFiles(join(repoRoot, "features/profile"))) {
    const lines = readFileSync(file, "utf8").split("\n");
    lines.forEach((line, index) => {
      if (
        line.includes("multi-workspace support") ||
        /TODO[^\n]*organizationId/.test(line)
      ) {
        matches.push(`${relative(repoRoot, file)}:${index + 1}`);
      }
    });
  }
  return matches;
}

/**
 * The text of the `/** … *\/` block that ends directly before
 * `export async function getProfileData` (only whitespace between), its ` * `
 * prefixes stripped and its lines joined with spaces; `null` when there is none.
 */
function getProfileDataDocComment(source: string): string | null {
  const declaration = source.indexOf("export async function getProfileData");
  if (declaration === -1) return null;
  const before = source.slice(0, declaration).trimEnd();
  if (!before.endsWith("*/")) return null;
  const start = before.lastIndexOf("/**");
  if (start === -1) return null;
  return before
    .slice(start + 3, before.length - 2)
    .split("\n")
    .map((line) => line.replace(/^\s*\*\s?/, "").trim())
    .filter((line) => line !== "")
    .join(" ");
}

describe("profile-todo-cleanup source", () => {
  it("AC-1: no file under features/profile/ mentions multi-workspace support or a TODO about an organizationId parameter", () => {
    expect(staleTodoMatches()).toEqual([]);
  });

  it("AC-2: the getProfileData doc comment has one sentence saying the profile is per person, not per workspace, so getProfileData takes no organization id", () => {
    const source = readFileSync(
      join(repoRoot, "features/profile/services/get-profile.ts"),
      "utf8",
    );
    const comment = getProfileDataDocComment(source);
    expect(comment).not.toBeNull();

    const sentences = (comment ?? "")
      .split(/\.\s+/)
      .map((sentence) => sentence.trim());
    const rule = sentences.filter(
      (sentence) =>
        /per person/i.test(sentence) &&
        /not per workspace/i.test(sentence) &&
        /no organization id/i.test(sentence) &&
        sentence.includes("getProfileData"),
    );
    expect(rule.length).toBeGreaterThan(0);
  });
});

