import { spawnSync } from "node:child_process";
import { mkdtempSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

import { describe, expect, it } from "vitest";

/**
 * profile-todo-cleanup — AC-3: on the changed tree, the existing unit tests
 * under features/profile/ all pass with the project's Vitest runner.
 *
 * The child run must not inherit the gate's reporter variables: vitest.config.ts
 * adds a JSON / JUnit reporter from them, and a child writing PHARN_TEST_RESULTS
 * would overwrite the gate's own per-test record. It writes its own JSON report
 * to a temporary directory instead.
 */

const repoRoot = join(__dirname, "..");

/** The parent's environment without the reporter variables or Vitest's own worker state. */
function childEnv(): NodeJS.ProcessEnv {
  const env: NodeJS.ProcessEnv = {};
  for (const [key, value] of Object.entries(process.env)) {
    if (key === "PHARN_TEST_RESULTS") continue;
    if (key.startsWith("VITEST")) continue;
    env[key] = value;
  }
  return env;
}

type VitestJsonReport = { numTotalTests: number; numFailedTests: number };

describe("profile-todo-cleanup suite", () => {
  it("AC-3: every existing unit test under features/profile/ passes on the changed tree", () => {
    const source = readFileSync(
      join(repoRoot, "features/profile/services/get-profile.ts"),
      "utf8",
    );
    // The changed tree: the stale workspace TODO is gone.
    expect(source).not.toContain("multi-workspace support");

    const outDir = mkdtempSync(join(tmpdir(), "profile-todo-cleanup-"));
    try {
      const outputFile = join(outDir, "result.json");
      const child = spawnSync(
        process.execPath,
        [
          "node_modules/vitest/vitest.mjs",
          "run",
          "features/profile/",
          "--reporter=json",
          `--outputFile=${outputFile}`,
        ],
        {
          cwd: repoRoot,
          env: childEnv(),
          encoding: "utf8",
          maxBuffer: 64 * 1024 * 1024,
        },
      );

      expect(child.status).toBe(0);
      const report = JSON.parse(
        readFileSync(outputFile, "utf8"),
      ) as VitestJsonReport;
      expect(report.numTotalTests).toBeGreaterThan(0);
      expect(report.numFailedTests).toBe(0);
    } finally {
      rmSync(outDir, { recursive: true, force: true });
    }
  }, 180_000);
});
